import java.util.ArrayList;

//Esta clase es necesaria por que este es mi ArrayList de Registro
public class Registro {

	//Atributo: El arrayList en cuestión
    private ArrayList<Modulo> modulos;

	//Constructor Default - No tengo el lleno por que siempre lo crearé vacío desde un comienzo.
    public Registro() {
        modulos = new ArrayList<Modulo>();
    }

	//Agregar un nuevo Modulo
    public void registrarModulo(Modulo modulo) {
		//Si el codigo incorporado no existe (osea, == null), entonces créalo
        if (buscarId(modulo.getId()) == null) {
            modulos.add(modulo);
        }
    }

	//Buscar por id
    public Modulo buscarId(String id) {
		//Para cada Modulo en modulos (mi arrayList)
        for (Modulo modulo : modulos) {
			//Si el id insertado coincide con el id del modulo
            if (modulo.getId().equals(id)) {
				//Entonces devuelve ese modulo
                return modulo;
            }
        }
		//Luego de todo, no regreses nada (no impacta si hay un return modulo)
        return null;
    }

	//Buscar, pero ahora por nombre
    public Modulo buscarNombre(String nombre) {
		//Para cada modulo en modulos
        for (Modulo modulo : modulos) {
			//Revisa si coincide el nombre con el de este modulo. Si sí, regresalo.
            if (modulo.getNombre().equals(nombre)) {
                return modulo;
            }
        }
        return null;
    }

	//Mostrar el ArrayList
    public void mostrarModulos() {
		//Para cada modulo en modulos
        for (Modulo modulo : modulos) {
			//Muestra el modulo y sus características.
            System.out.println(modulo);
            modulo.mostrarCaracteristicas();
            System.out.println();
        }
    }

	//Como se pide un catálogo por Costo, pero no quiero modificar el orden
    public void mostrarCatalogoCosto() {

        // Se crea una copia para no modificar el orden original de los módulos. (Asi el orden se mantiene)
        ArrayList<Modulo> copia = new ArrayList<Modulo>(modulos);

        // Ordenar de menor a mayor costo (no se deçia que orden? Asi que decidi en orden creciente)
		//Sí, pedi ayuda acá, pero ahorita explico que hace esto

		//Son doble for por que tenemos que poder odenar la copia, y recorrerla para poder modificarla en el segundo for.
        for (int i = 0; i < copia.size() - 1; i++) {
            for (int j = i + 1; j < copia.size(); j++) {
                if (copia.get(i).getCosto()> copia.get(j).getCosto()) {
                    Modulo temporal = copia.get(i);
                    copia.set(i, copia.get(j));
                    copia.set(j, temporal);
                }
            }
        }

		//Ahora muestra el nuevo orden, con el Array copia y su nuevo orden. Esto se hizo así para mantener el orden original.
        System.out.println("\nCATÁLOGO POR COSTO\n");
        for (Modulo modulo : copia) {

            System.out.println(modulo);
            modulo.mostrarCaracteristicas();
            System.out.println();
        }
    }

//Puesw bien, necesito avanzar el Ciclo
    public void avanzarCiclo(Mision mision) {
        System.out.println("\nINICIO DEL CICLO\n");
		//Para cada modulo
        for (Modulo modulo : modulos) {
			//Hacer el proceso del modulo para el orden del modulo original
			//Y esto también ALTERA los recursos
            modulo.procesoCiclo(mision);
            System.out.println("Energía disponible: "+ mision.getEnergiaDisponible());
            System.out.println("Datos en órbita: " + mision.getDatosOrbita()+" MB");
			System.out.println("Datos descargados: "+ mision.getDatosDescarga()+ " MB");
            System.out.println();
        }

		//Ciclos totales + 1 al conteo
        mision.setCiclosTotales(mision.getCiclosTotales() + 1);
        System.out.println("FIN DEL CICLO");
        System.out.println(mision);
    }

//Historial de los modulos de Tierra (comunicaciones)
    public void resumenComunicaciones() {

        int cantidadTierra = 0;
        int tierraActivos = 0;
        int capacidadActivos = 0;
        int historicoDescargado = 0;
        int mayorDescarga = -1;


        // Primer recorrido: calcular cantidades, capacidad, histórico y máximo
        for (Modulo modulo : modulos) {
			//Por eso el clase es un int, para este if
            if (modulo.getClase() == 1) {
                ModuloTierra tierra = (ModuloTierra) modulo;
				//Aumenta en 1 la cantidad de modulos de Tierra
                cantidadTierra++;

				//Si esta activo
                if (tierra.getActivo()) {
					//Aumenta en 1 la cantidad de Modulos activados
					//aumenta la capacidad
					tierraActivos++;
					capacidadActivos += tierra.getCapacidad();
                }

				//Trae cuanto fue descargado a lol largo de la misión
                historicoDescargado += tierra.getTotalDescargado();

				//Si el total Descargado de este modulo es mayor a la mayor Descarga, entonces ESTE es el que más ha descargado.
                if (tierra.getTotalDescargado() > mayorDescarga) {
                    mayorDescarga = tierra.getTotalDescargado();
                }
            }
        }


        System.out.println("\nRESUMEN DE COMUNICACIONES\n");
        System.out.println("Módulos de Tierra: " + cantidadTierra);
        System.out.println("Módulos de Tierra activos: " + tierraActivos);
        System.out.println("Capacidad total de descarga de los activos: "+ capacidadActivos+ " MB por ciclo");
        System.out.println("Total histórico descargado: " + historicoDescargado + " MB");

        // Segundo recorrido:mostrar todos los módulos empatados con el máximo
        if (cantidadTierra > 0) {
            System.out.println("\nMódulo(s) con mayor descarga histórica:");
			//Otra vez, necesito revisar si es de Tierra y si está empatado con el mayor, e imprimir todos los que están empatados
            for (Modulo modulo : modulos) {
                if (modulo.getClase() == 1) {
                    ModuloTierra tierra =
                        (ModuloTierra) modulo;
                    if (tierra.getTotalDescargado() == mayorDescarga) {
                        System.out.println("Nombre: " + tierra.getNombre());
						System.out.println("ID: " + tierra.getId());
                        System.out.println("Estación: "+ tierra.getEstacion());
                        System.out.println("Total descargado: "+ tierra.getTotalDescargado()+ " MB");
                        System.out.println();
                    }
                }
            }

		//Solo por si no hay nada
        } else {

            System.out.println(
                "No hay módulos de Tierra registrados."
            );
        }
    }
}